package com.steadyme.app;
import android.content.*; import android.os.Bundle; import android.util.Patterns; import android.view.View; import android.widget.Toast; import androidx.appcompat.app.AppCompatActivity; import com.google.firebase.auth.FirebaseAuth; import com.steadyme.app.databinding.ActivityLoginBinding;
public class LoginActivity extends AppCompatActivity { private ActivityLoginBinding binding; private FirebaseAuth auth;
 @Override public void onCreate(Bundle b){super.onCreate(b);binding=ActivityLoginBinding.inflate(getLayoutInflater());setContentView(binding.getRoot());auth=FirebaseAuth.getInstance(); if(auth.getCurrentUser()!=null){openMain();return;} binding.btnLogin.setOnClickListener(v->login()); binding.tvRegister.setOnClickListener(v->startActivity(new Intent(this,SignupActivity.class)));}
 private void login(){String email=binding.etEmail.getText()==null?"":binding.etEmail.getText().toString().trim(), password=binding.etPassword.getText()==null?"":binding.etPassword.getText().toString();binding.tilEmail.setError(null);binding.tilPassword.setError(null);if(!Patterns.EMAIL_ADDRESS.matcher(email).matches()){binding.tilEmail.setError("Enter a valid email address");return;}if(password.length()<6){binding.tilPassword.setError("Password must be at least 6 characters");return;}binding.progressLogin.setVisibility(View.VISIBLE);binding.btnLogin.setEnabled(false);auth.signInWithEmailAndPassword(email,password).addOnSuccessListener(x->openMain()).addOnFailureListener(e->{binding.progressLogin.setVisibility(View.GONE);binding.btnLogin.setEnabled(true);Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();});}
 private void openMain(){startActivity(new Intent(this,MainActivity.class));finish();}
}
